import hashlib,json,shutil
from pathlib import Path
root=Path('evidence/development/presentation-states')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();write=lambda p,j:p.write_text(json.dumps(j,indent=2)+'\n')
env=json.load(open(root/'build-environment.json'))
for p,h in env['sourceInputs'].items():assert sha(Path(p))==h,p
native=json.load(open('evidence/reference-proposals/presentation-states-20261015-v2/captures.json'))['captures']
actions=[]
for c in native:
 if c['api'] not in ('BleeckerEmptyState','BleeckerErrorState') or c['actionsMode']!='button':continue
 m=json.load(open(root/'captures'/(c['path']+'.json')))
 buttons=[b for b in m['labels'] if b['role']=='' and b['text']=='Create 0'];assert len(buttons)==2,c['path']
 for b in buttons:
  for axis in ('width','height'):assert abs(b[axis]-c['actionRect'][axis])<=1e-6,(c['path'],axis)
 actions.append({'fixture':c['path'],'sourceActionSize':{k:c['actionRect'][k] for k in ('width','height')},'qtActionSizes':[{k:b[k] for k in ('width','height')} for b in buttons],'status':'matched source action bounds'})
assert len(actions)==184
write(root/'action-geometry.json',{'cases':184,'results':actions})
write(root/'feature-path-audit.json',{'path':['title/message/defaults and nullable icon/action Component producers','fitted source-font layout, centered wrapped messages, finite button-label proposals and original glyph candidates','owned Qt template action input/disabled guards and actual Qt accessibility actions','stable action factories across producer updates; owner/factory removal and recreation reset private state','loading offered rectangle, original spinner candidate, clipped card and pointer blocker with successful positive controls','outside action/editing, focus preservation and input restoration after overlay removal','normal catalog, isolated valid source cases and independently installed consumer under both display protocols/renderers/profiles'],'unaffected':['source pins, expected captures, tolerances, approved exceptions and TV','backend/metrics, authentication and application configuration'],'remaining':['Exact glyph/raster and native spinner presentation/animation phase','Native DPR 1 loading and active-window context','Broader generic composition, constrained loading/variant buttons, scripts and RTL multiline text','Source keyboard/focus/modal/safe-area and actual readers','Physical input/display and the separately selected TV target','Fresh complete Sabella source compilation and public capture-helper distribution']})
shutil.copy2('artifacts/presentation-implementation/package-identity.json',root/'package-identity.json')
shutil.copy2('artifacts/presentation-implementation/native-loading/verification.log',root/'native-loading-verification.log')
shutil.copy2('artifacts/presentation-implementation/native-loading/replay.log',root/'native-loading-replay.log')
write(root/'source-renderer-correction.json',{'unsupportedSourceDirectory':'evidence/reference-investigations/presentation-states-20261014','unsupportedLoadingImageRendererCaptures':64,'reason':'Visual review found unsupported-view markers for the NSView-backed ProgressView. Original immutable images remain diagnostics and are excluded from visual proposals.','correctedSource':'evidence/reference-investigations/loading-native-20261015','actualNativeProgressCaptures':32,'nativeDprs':[2],'nativeReplayFilesByteIdentical':33,'staticSourceToolReplayFilesByteIdentical':431,'correctedProposalCaptures':272,'missing':'Actual native DPR 1, active-window and animation-phase acceptance remain pending.','linuxValidation':'A full corrected run and a fresh independent 112-pair package matrix are required; preceding first-run results remain preserved locally and are not substituted.'})
rows=json.load(open(root/'comparison/comparison.json'))['results']
for name in ['preserve.py','finish-evidence.py','stage-audit.py']:shutil.copy2(Path('artifacts/presentation-implementation')/name,root/name)
j={'schemaVersion':1,'status':'presentation state runtime, source state and root-bound candidates verified; complete mirror acceptance pending','previousCandidate':'25e56280b685c51d731ac26636597cf0a5953470','reference':'evidence/reference-proposals/presentation-states-20261015-v2/proposal.json','captures':272,'newStateCases':264,'geometryMatches':sum(r.get('geometryStatus')=='passed' for r in rows),'exactMatches':sum(r['status']=='passed' for r in rows),'apiSummary':json.load(open(root/'comparison/api-summary.json')),'sourceActionBoundsMatched':184,'sourcePointerLifecycleCases':68,'qtSourcePointerLifecycleChecks':136,'qtChecks':3646,'contractTests':77,'invalidStartupRefusals':15,'installedOffscreenModes':14,'virtualInstalledWindowPairs':112,'presentationVirtualWindowPairs':8,'installedCatalogCaptures':67,'priorRegressionImagesAndMetadataUnchanged':2978,'nativeLoadingReplay':'native-replay.json','approvedExceptions':[],'limitations':['Root geometry, source state and action-size matches do not establish complete visual or generic composition acceptance.','Original glyphs and existing spinner candidate remain unaccepted; native animation phase and actual native DPR 1 are unverified.','All 64 unsupported historical ImageRenderer loading images are excluded from the visual proposal.','Software rounded-content clipping and real GPU/physical boundaries remain separate acceptance work.','Native capture helpers link preserved source-verified objects, not a fresh complete source build, and have no public download endpoint.','The fresh complete source-input snapshots contain preceding main plus dirty input hashes; virtual software/Mesa and synthetic input remain separate from physical evidence.','No source pin, expected capture, tolerance or exception changed.']}
j['files']={str(p.relative_to(root)):sha(p) for p in sorted(root.rglob('*')) if p.is_file() and p.name!='candidate.json'};write(root/'candidate.json',j)
print('Sealed',len(j['files']),'files;',len(env['sourceInputs']),'tested inputs; source action bounds',len(actions));print({k:v for k,v in j.items() if k not in ('files','apiSummary','limitations')})
